"use client";

import { Dialog } from "@base-ui/react/dialog";
import { ArrowLeftIcon, CircleHelpIcon, EyeIcon, PlusIcon, XIcon } from "lucide-react";
import { useMemo, useRef, useState, type ComponentType, type ReactNode } from "react";

import { ActionToastProvider, useActionToast } from "@/components/action-toast";
import { IconTooltip } from "@/components/icon-tooltip";
import { Link, type LinkProps } from "@/components/link";
import { useLoadingActivity } from "@/components/loading-indicator";
import { SupportComposer } from "@/components/plugins/supports/composer";
import { supportsLabels, type SupportsLabels } from "@/components/plugins/supports/labels";
import { SUPPORT_PAGE_SIZE } from "@/components/plugins/supports/schema";
import type {
  SupportActivity,
  SupportTicket,
  SupportsClient,
} from "@/components/plugins/supports/types";
import {
  SupportAttachments,
  SupportMarkdown,
  SupportStatusBadge,
  buttonClass,
  primaryClass,
  supportError,
} from "@/components/plugins/supports/ui";
import { TablePagination } from "@/components/table-pagination";
import { TableSearch } from "@/components/table-search";
import { cn } from "@/components/utils/cn";
import {
  tablePanelClass,
  tableClass,
  tableHeaderClass,
  tableRowClass,
  tableCellClass,
  tableActionCellClass,
  tableActionHeaderClass,
  tableActionsClass,
} from "@/components/utils/table-styles";
import { useOptimisticAction } from "@/components/utils/use-optimistic-action";

export type * from "./types";
export type { SupportsLabels } from "./labels";
export { supportsLabels } from "./labels";
interface Appearance {
  className?: string;
  labels?: Partial<SupportsLabels>;
  linkComponent?: ComponentType<LinkProps>;
  formatDate?: (iso: string) => string;
}
const formatDateDefault = (iso: string) =>
  new Intl.DateTimeFormat("en", { dateStyle: "medium", timeZone: "UTC" }).format(new Date(iso));
export interface SupportCreateDialogProps extends Appearance {
  client: SupportsClient;
  onCreated?: (ticket: SupportTicket) => void;
  disabled?: boolean;
}
export function SupportCreateDialog({
  client,
  onCreated,
  disabled,
  labels: overrides,
  className,
}: SupportCreateDialogProps) {
  const labels = { ...supportsLabels, ...overrides };
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  return (
    <ActionToastProvider closeLabel={labels.close}>
      <Dialog.Root
        open={open}
        onOpenChange={(value) => {
          if (!pending) setOpen(value);
        }}
      >
        <Dialog.Trigger disabled={disabled} className={cn(primaryClass, className)}>
          <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
          {labels.add}
        </Dialog.Trigger>
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup className="fixed top-1/2 left-1/2 z-50 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-xl -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-xl border border-border bg-background px-6 text-foreground shadow-lg">
            <div className="sticky top-0 z-10 -mx-6 space-y-2 bg-background px-6 pt-5 pb-4">
              <div className="flex items-start justify-between gap-3">
                <Dialog.Title className="text-lg font-semibold">{labels.createTitle}</Dialog.Title>
                <IconTooltip label={labels.close}>
                  <Dialog.Close
                    disabled={pending}
                    aria-label={labels.close}
                    className={cn(buttonClass, "size-8 shrink-0 p-0")}
                  >
                    <XIcon aria-hidden="true" className="size-4" />
                  </Dialog.Close>
                </IconTooltip>
              </div>
              <Dialog.Description className="text-sm text-muted-foreground">
                {labels.instructions}
              </Dialog.Description>
            </div>
            <div className="pb-5">
              <SupportComposer
                client={client}
                labels={labels}
                onPendingChange={setPending}
                onCancel={() => setOpen(false)}
                onCreated={(ticket) => {
                  setPending(false);
                  setOpen(false);
                  onCreated?.(ticket);
                }}
              />
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
    </ActionToastProvider>
  );
}
export interface SupportsPageProps extends Appearance {
  client: SupportsClient;
  tickets: readonly SupportTicket[];
  total: number;
  search: string;
  page: number;
  onSearchChange: (search: string) => void;
  onPageChange: (page: number) => void;
  getTicketHref: (ticket: SupportTicket) => string;
  onChanged?: () => void;
  onCreated?: (ticket: SupportTicket) => void;
  loading?: boolean;
  error?: boolean;
  onRetry?: () => void;
}
function SupportsContent({
  client,
  tickets,
  total,
  search,
  page,
  onSearchChange,
  onPageChange,
  getTicketHref,
  onChanged,
  onCreated,
  loading,
  error,
  onRetry,
  labels: overrides,
  linkComponent: TicketLink = Link,
  formatDate = formatDateDefault,
  className,
}: SupportsPageProps) {
  const labels = { ...supportsLabels, ...overrides };
  const toast = useActionToast();
  const scope = useMemo(() => ({ client, search, page }), [client, search, page]);
  const cancellation = useOptimisticAction(tickets, scope);
  useLoadingActivity(Boolean(loading));
  return (
    <section className={cn("min-w-0 space-y-5 text-foreground", className)}>
      <header className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="flex items-center gap-2 text-xl font-semibold">
          <CircleHelpIcon className="size-5 shrink-0" aria-hidden="true" />
          {labels.title}
        </h1>
        <div className="flex max-w-full flex-wrap items-center gap-2">
          <TableSearch
            value={search}
            onValueChange={onSearchChange}
            label={labels.search}
            clearLabel={labels.clearSearch}
            maxLength={250}
          />
          <SupportCreateDialog client={client} labels={labels} onCreated={onCreated} />
        </div>
      </header>
      <div className={tablePanelClass} aria-busy={loading}>
        <div className="overflow-x-auto">
          <table className={tableClass}>
            <thead>
              <tr>
                {[
                  labels.ticketTitle,
                  labels.type,
                  labels.status,
                  labels.author,
                  labels.updated,
                ].map((label, index) => (
                  <th key={index} scope="col" className={tableHeaderClass}>
                    {label}
                  </th>
                ))}
                <th scope="col" className={tableActionHeaderClass}>
                  <span className="sr-only">{labels.actions}</span>
                </th>
              </tr>
            </thead>
            <tbody>
              {cancellation.error && (
                <tr>
                  <td colSpan={6} className="p-4">
                    <p role="alert" className="text-destructive">
                      {supportError(cancellation.error, {
                        ...labels,
                        saveError: labels.cancelError,
                      })}
                    </p>
                  </td>
                </tr>
              )}
              {error && (
                <tr>
                  <td colSpan={6} className="p-4">
                    <div className="flex flex-wrap items-center gap-2">
                      <p role="alert" className="text-destructive">
                        {labels.loadError}
                      </p>
                      {onRetry && (
                        <button type="button" className={buttonClass} onClick={onRetry}>
                          {labels.retry}
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              )}
              {!tickets.length && !error && (
                <tr>
                  <td colSpan={6} className="p-8 text-center text-muted-foreground">
                    <output>{loading ? labels.loading : labels.empty}</output>
                  </td>
                </tr>
              )}
              {cancellation.value.map((ticket) => (
                <tr key={ticket.id} className={tableRowClass}>
                  <td className={tableCellClass}>
                    <TicketLink
                      href={getTicketHref(ticket)}
                      className="inline-flex min-h-10 items-center rounded-sm font-medium text-primary underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-ring md:min-h-8"
                    >
                      {ticket.title}
                    </TicketLink>
                  </td>
                  <td className={tableCellClass}>{labels[ticket.type]}</td>
                  <td className={tableCellClass}>
                    <SupportStatusBadge status={ticket.status} labels={labels} />
                  </td>
                  <td className={tableCellClass}>{ticket.author.name}</td>
                  <td className={cn(tableCellClass, "whitespace-nowrap tabular-nums")}>
                    <time dateTime={ticket.updatedAt}>{formatDate(ticket.updatedAt)}</time>
                  </td>
                  <td className={tableActionCellClass} aria-label={labels.actions}>
                    <div className={tableActionsClass}>
                      <IconTooltip label={labels.view}>
                        <TicketLink
                          href={getTicketHref(ticket)}
                          aria-label={`${labels.view}: ${ticket.title}`}
                          className={cn(buttonClass, "size-10 p-0 md:size-8")}
                        >
                          <EyeIcon className="size-4 shrink-0" aria-hidden="true" />
                        </TicketLink>
                      </IconTooltip>
                      <IconTooltip label={labels.cancelTicket}>
                        <button
                          type="button"
                          aria-label={`${labels.cancelTicket}: ${ticket.title}`}
                          className={cn(
                            buttonClass,
                            "size-10 p-0 enabled:text-destructive md:size-8",
                          )}
                          disabled={
                            ticket.status !== "open" || loading || error || cancellation.pending
                          }
                          onClick={() => {
                            void cancellation
                              .run(
                                (current) =>
                                  current.map((entry) =>
                                    entry.id === ticket.id
                                      ? { ...entry, status: "canceled" }
                                      : entry,
                                  ),
                                () => client.setStatus(ticket.id, "canceled"),
                                () => {
                                  toast(labels.statusSaved);
                                  onChanged?.();
                                },
                              )
                              .catch(() => {});
                          }}
                        >
                          <XIcon className="size-4 shrink-0" aria-hidden="true" />
                        </button>
                      </IconTooltip>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <TablePagination
          summary={labels.total(total)}
          page={page}
          pageCount={Math.max(1, Math.ceil(total / SUPPORT_PAGE_SIZE))}
          previousDisabled={page <= 1}
          nextDisabled={page * SUPPORT_PAGE_SIZE >= total}
          disabled={loading}
          onPrevious={() => onPageChange(page - 1)}
          onNext={() => onPageChange(page + 1)}
          label={labels.pagination}
          previousLabel={labels.previous}
          nextLabel={labels.next}
        />
      </div>
    </section>
  );
}
export function SupportsPage(props: SupportsPageProps) {
  return (
    <ActionToastProvider closeLabel={props.labels?.close}>
      <SupportsContent {...props} />
    </ActionToastProvider>
  );
}
export interface SupportDetailPageProps extends Appearance {
  integrationContent?: ReactNode;
  client: SupportsClient;
  ticket: SupportTicket;
  activity: readonly SupportActivity[];
  backHref: string;
  onChanged: () => void;
  onLoadMore?: () => void;
  loading?: boolean;
  error?: boolean;
}
function DetailContent({
  integrationContent,
  client,
  ticket,
  activity,
  backHref,
  onChanged,
  onLoadMore,
  loading,
  error,
  labels: overrides,
  linkComponent: TicketLink = Link,
  formatDate = formatDateDefault,
  className,
}: SupportDetailPageProps) {
  const labels = { ...supportsLabels, ...overrides };
  const toast = useActionToast();
  const scope = useMemo(() => ({ client, id: ticket.id }), [client, ticket.id]);
  const status = useOptimisticAction(ticket.status, scope);
  const [closeScope, setCloseScope] = useState<typeof scope | null>(null);
  const statusButton = useRef<HTMLButtonElement>(null);
  const cancelButton = useRef<HTMLButtonElement>(null);
  const confirming = closeScope === scope;
  const dangerClass =
    "border-destructive/20 bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30 disabled:border-border disabled:bg-muted disabled:text-muted-foreground dark:disabled:bg-muted";
  function changeStatus(next: "open" | "closed") {
    void status
      .run(
        () => next,
        () => client.setStatus(ticket.id, next),
        () => {
          setCloseScope(null);
          toast(labels.statusSaved);
          onChanged();
        },
      )
      .catch(() => {});
  }
  useLoadingActivity(Boolean(loading));
  return (
    <article className={cn("mx-auto max-w-4xl min-w-0 text-foreground", className)}>
      <SupportComposer
        key={ticket.id}
        client={client}
        ticketId={ticket.id}
        labels={labels}
        onChanged={onChanged}
        actions={
          <button
            ref={statusButton}
            className={cn(buttonClass, status.value === "open" && dangerClass)}
            disabled={loading || status.pending}
            type="button"
            onClick={() => {
              if (status.value === "open") setCloseScope(scope);
              else changeStatus("open");
            }}
          >
            {status.value === "open" ? labels.closeTicket : labels.reopen}
          </button>
        }
      >
        <TicketLink href={backHref} className={buttonClass}>
          <ArrowLeftIcon className="size-4 shrink-0" aria-hidden="true" />
          {labels.back}
        </TicketLink>
        <header className="space-y-3">
          <div className="flex items-start justify-between gap-3">
            <h1 className="min-w-0 text-2xl font-semibold break-words">{ticket.title}</h1>
            <SupportStatusBadge status={status.value} labels={labels} />
          </div>
          <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground">
            <span>{labels[ticket.type]}</span>
            <span>{ticket.author.name}</span>
            <time dateTime={ticket.createdAt}>{formatDate(ticket.createdAt)}</time>
          </div>
        </header>
        {integrationContent}
        {status.error && !confirming && (
          <p role="alert" className="text-sm text-destructive">
            {supportError(status.error, labels)}
          </p>
        )}
        {error && (
          <div className="flex flex-wrap items-center gap-2">
            <p role="alert" className="text-sm text-destructive">
              {labels.loadError}
            </p>
            <button className={buttonClass} type="button" onClick={onChanged}>
              {labels.retry}
            </button>
          </div>
        )}
        <SupportMarkdown value={ticket.description} />
        <SupportAttachments files={ticket.attachments} client={client} labels={labels} />
        <section className="space-y-5 border-t border-border pt-5" aria-label={labels.discussion}>
          <h2 className="text-lg font-semibold">{labels.discussion}</h2>
          {!activity.length && <p className="text-sm text-muted-foreground">{labels.noActivity}</p>}
          <ol className="space-y-5">
            {activity.map((entry) => (
              <li key={entry.id} className="min-w-0 space-y-3 border-b border-border pb-5">
                <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
                  <span className="font-medium">{entry.author.name}</span>
                  {entry.kind === "status" && (
                    <span>
                      {entry.status === "canceled"
                        ? labels.canceledActivity
                        : entry.status === "closed"
                          ? labels.closedActivity
                          : labels.reopenedActivity}
                    </span>
                  )}
                  <time
                    className="ml-auto text-xs text-muted-foreground"
                    dateTime={entry.createdAt}
                  >
                    {formatDate(entry.createdAt)}
                  </time>
                </div>
                {entry.body && <SupportMarkdown value={entry.body} />}
                <SupportAttachments files={entry.attachments} client={client} labels={labels} />
              </li>
            ))}
          </ol>
          {onLoadMore && (
            <button className={buttonClass} disabled={loading} onClick={onLoadMore} type="button">
              {labels.loadMore}
            </button>
          )}
        </section>
      </SupportComposer>
      <Dialog.Root
        open={confirming}
        onOpenChange={(open) => {
          if (!open && !status.pending) setCloseScope(null);
        }}
      >
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup
            initialFocus={cancelButton}
            finalFocus={statusButton}
            className="fixed top-1/2 left-1/2 z-50 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 scroll-py-32 space-y-5 overflow-y-auto rounded-xl border border-border bg-card px-6 text-card-foreground shadow-xl"
          >
            <div
              data-dialog-header
              className="sticky top-0 z-20 -mx-6 mb-0 flex items-start justify-between gap-3 bg-card px-6 pt-5 pb-2"
            >
              <Dialog.Title className="min-w-0 flex-1 text-lg font-semibold break-words">
                {labels.closeTitle}
              </Dialog.Title>
              <IconTooltip label={labels.close}>
                <Dialog.Close
                  type="button"
                  aria-label={labels.close}
                  disabled={status.pending}
                  className={cn(buttonClass, "size-10 p-0 md:size-8")}
                >
                  <XIcon className="size-4 shrink-0" aria-hidden="true" />
                </Dialog.Close>
              </IconTooltip>
            </div>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.closeDescription}
            </Dialog.Description>
            <div className="min-h-5 text-sm text-destructive">
              {status.error && <p role="alert">{supportError(status.error, labels)}</p>}
            </div>
            <div
              data-dialog-footer
              className="sticky bottom-0 z-10 -mx-6 flex flex-wrap justify-end gap-2 bg-card px-6 pt-0 pb-5"
            >
              <Dialog.Close ref={cancelButton} className={buttonClass} disabled={status.pending}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="button"
                className={cn(buttonClass, dangerClass)}
                disabled={loading || status.pending || status.value !== "open"}
                aria-busy={status.pending}
                onClick={() => changeStatus("closed")}
              >
                {status.pending ? labels.saving : labels.closeTicket}
              </button>
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
    </article>
  );
}
export function SupportDetailPage(props: SupportDetailPageProps) {
  return (
    <ActionToastProvider closeLabel={props.labels?.close}>
      <DetailContent key={props.ticket.id} {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { XIcon } from "lucide-react";
import { useEffect, useLayoutEffect, useId, useRef, useState, type ReactNode } from "react";

import { useActionToast } from "@/components/action-toast";
import { IconTooltip } from "@/components/icon-tooltip";
import { NativeSelect } from "@/components/native-select";
import type { SupportsLabels } from "@/components/plugins/supports/labels";
import {
  SUPPORT_IMAGE_TYPES,
  SUPPORT_MAX_IMAGES,
  SUPPORT_MAX_IMAGE_BYTES,
  supportCreateSchema,
  supportCommentSchema,
} from "@/components/plugins/supports/schema";
import type {
  SupportsClient,
  SupportTicket,
  SupportType,
} from "@/components/plugins/supports/types";
import {
  buttonClass,
  primaryClass,
  inputClass,
  supportError,
} from "@/components/plugins/supports/ui";
import { cn } from "@/components/utils/cn";
import { submitFormOnShortcut } from "@/components/utils/dialog-submit";
import { editorActionsClass } from "@/components/utils/editor-form";
import { useMutationAction } from "@/components/utils/use-optimistic-action";

type SelectedFile = { file: File; requestId: string; url: string; attachmentId?: string };
export function SupportComposer({
  client,
  ticketId,
  labels,
  onCreated,
  onChanged,
  onPendingChange,
  onCancel,
  children,
  actions,
}: {
  client: SupportsClient;
  ticketId?: string;
  labels: SupportsLabels;
  onCreated?: (ticket: SupportTicket) => void;
  onChanged?: () => void;
  onPendingChange?: (pending: boolean) => void;
  onCancel?: () => void;
  children?: ReactNode;
  actions?: ReactNode;
}) {
  const id = `factory-support-composer-${useId()}`;
  const toast = useActionToast();
  const mutation = useMutationAction(client);
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [type, setType] = useState<SupportType | "">("");
  const [files, setFiles] = useState<SelectedFile[]>([]);
  const [error, setError] = useState("");
  const selected = useRef(files);
  useLayoutEffect(() => {
    selected.current = files;
  }, [files]);
  const attempt = useRef<{ fingerprint: string; requestId: string } | null>(null);
  useEffect(
    () => () => {
      for (const entry of selected.current) {
        URL.revokeObjectURL(entry.url);
        if (entry.attachmentId) void client.cancelUpload(entry.attachmentId).catch(() => {});
      }
    },
    [client],
  );
  async function remove(entry: SelectedFile) {
    setError("");
    const accepted = await mutation.run(
      async () => {
        if (entry.attachmentId) await client.cancelUpload(entry.attachmentId);
      },
      () => {
        URL.revokeObjectURL(entry.url);
        setFiles((values) => values.filter((value) => value !== entry));
      },
    );
    if (!accepted && mutation.isCurrent()) setError(labels.saveError);
  }
  async function submit() {
    if (mutation.pending) return;
    setError("");
    const value = {
      title,
      description: body,
      type,
      body,
      id: ticketId,
      attachmentIds: files.map((file) => file.requestId),
      requestId: "validate",
    };
    if (!(ticketId ? supportCommentSchema : supportCreateSchema).safeParse(value).success) {
      setError(labels.invalid);
      return;
    }
    onPendingChange?.(true);
    const accepted = await mutation.run(
      async () => {
        for (const entry of files) {
          if (!mutation.isCurrent()) throw new Error("Composer departed");
          if (!entry.attachmentId) {
            const file = await client.upload({ requestId: entry.requestId, file: entry.file });
            entry.attachmentId = file.id;
            if (!mutation.isCurrent()) {
              void client.cancelUpload(file.id).catch(() => {});
              throw new Error("Composer departed");
            }
          }
        }
        const attachmentIds = files.map((file) => file.attachmentId!);
        const fingerprint = JSON.stringify([title, body, type, attachmentIds]);
        if (attempt.current?.fingerprint !== fingerprint)
          attempt.current = { fingerprint, requestId: crypto.randomUUID() };
        const requestId = attempt.current.requestId;
        if (ticketId) {
          await client.comment({ id: ticketId, body, attachmentIds, requestId });
          return undefined;
        }
        return client.create(
          supportCreateSchema.parse({ title, description: body, type, attachmentIds, requestId }),
        );
      },
      (created) => {
        for (const entry of files) URL.revokeObjectURL(entry.url);
        selected.current = [];
        setFiles([]);
        setTitle("");
        setBody("");
        setType("");
        attempt.current = null;
        toast(created ? labels.created : labels.posted);
        if (created) onCreated?.(created);
        else onChanged?.();
      },
    );
    if (mutation.isCurrent()) {
      onPendingChange?.(false);
      if (!accepted) setError(labels.saveError);
    }
  }
  const failure = mutation.error ? supportError(mutation.error, labels) : error;
  return (
    <div onKeyDownCapture={submitFormOnShortcut}>
      <form
        className={ticketId ? "space-y-6" : "space-y-4"}
        onSubmit={(event) => {
          event.preventDefault();
          void submit();
        }}
        aria-busy={mutation.pending}
      >
        {children}
        <fieldset disabled={mutation.pending} className="min-w-0 space-y-4">
          {!ticketId && (
            <>
              <div className="space-y-2">
                <label htmlFor={`${id}-title`} className="text-sm font-medium">
                  {labels.ticketTitle} <span aria-hidden="true">*</span>
                </label>
                <input
                  id={`${id}-title`}
                  className={inputClass}
                  required
                  maxLength={200}
                  value={title}
                  onChange={(event) => setTitle(event.target.value)}
                />
              </div>
              <div className="space-y-2">
                <label htmlFor={`${id}-type`} className="text-sm font-medium">
                  {labels.type} <span aria-hidden="true">*</span>
                </label>
                <NativeSelect
                  id={`${id}-type`}
                  required
                  className={inputClass}
                  value={type}
                  onChange={(event) => setType(event.target.value as SupportType)}
                >
                  <option value="">{labels.chooseType}</option>
                  {(["bug", "feature", "support"] as const).map((value) => (
                    <option key={value} value={value}>
                      {labels[value]}
                    </option>
                  ))}
                </NativeSelect>
              </div>
            </>
          )}
          <div className="space-y-2">
            <label htmlFor={`${id}-body`} className="text-sm font-medium">
              {ticketId ? labels.reply : labels.description}{" "}
              {!ticketId && <span aria-hidden="true">*</span>}
            </label>
            <textarea
              id={`${id}-body`}
              className={cn(inputClass, "min-h-32 resize-y")}
              required={!ticketId}
              maxLength={5000}
              value={body}
              onChange={(event) => setBody(event.target.value)}
              aria-describedby={`${id}-markdown`}
            />
            <p id={`${id}-markdown`} className="text-xs text-muted-foreground">
              {labels.markdown}
            </p>
          </div>
          <div className="space-y-2">
            <label htmlFor={`${id}-images`} className="text-sm font-medium">
              {labels.images}
            </label>
            <input
              id={`${id}-images`}
              type="file"
              multiple
              accept={SUPPORT_IMAGE_TYPES.join(",")}
              className={cn(
                inputClass,
                "cursor-pointer file:mr-3 file:cursor-pointer file:border-0 file:bg-transparent file:text-sm file:text-foreground",
              )}
              aria-describedby={`${id}-limits`}
              onChange={(event) => {
                const additions = Array.from(event.target.files ?? []);
                event.target.value = "";
                if (
                  additions.length + files.length > SUPPORT_MAX_IMAGES ||
                  additions.some(
                    (file) =>
                      !SUPPORT_IMAGE_TYPES.includes(file.type) ||
                      !file.size ||
                      file.size > SUPPORT_MAX_IMAGE_BYTES,
                  )
                ) {
                  setError(labels.invalidImages);
                  return;
                }
                setError("");
                setFiles((current) => [
                  ...current,
                  ...additions.map((file) => ({
                    file,
                    requestId: crypto.randomUUID(),
                    url: URL.createObjectURL(file),
                  })),
                ]);
              }}
            />
            <p id={`${id}-limits`} className="text-xs text-muted-foreground">
              {labels.imagesHint}
            </p>
          </div>
          {files.length > 0 && (
            <ul className="flex flex-wrap gap-3">
              {files.map((entry) => (
                <li key={entry.requestId} className="relative w-28 space-y-1">
                  <img
                    src={entry.url}
                    alt={entry.file.name}
                    className="aspect-[4/3] w-full rounded-md border border-border object-contain"
                  />
                  <span className="block text-xs break-words">{entry.file.name}</span>
                  <IconTooltip label={`${labels.remove}: ${entry.file.name}`}>
                    <button
                      className={cn(buttonClass, "absolute top-1 right-1 size-8 bg-background p-0")}
                      type="button"
                      aria-label={`${labels.remove}: ${entry.file.name}`}
                      onClick={() => void remove(entry)}
                    >
                      <XIcon aria-hidden="true" className="size-4" />
                    </button>
                  </IconTooltip>
                </li>
              ))}
            </ul>
          )}
        </fieldset>
        {failure && (
          <p role="alert" className="text-sm text-destructive">
            {failure}
          </p>
        )}
        <div className={cn("flex flex-wrap justify-end gap-2", ticketId && editorActionsClass)}>
          {actions}
          {onCancel && (
            <button
              type="button"
              className={buttonClass}
              disabled={mutation.pending}
              onClick={onCancel}
            >
              {labels.cancel}
            </button>
          )}
          <button type="submit" className={primaryClass} disabled={mutation.pending}>
            {mutation.pending ? labels.saving : ticketId ? labels.post : labels.create}
          </button>
        </div>
      </form>
    </div>
  );
}

